/**
 * assets.js — sprite cắt từ ảnh tham chiếu portal-puzzle-404.png
 * (data URL WebP, cắt bằng Chrome headless + canvas). Floor/wall là tile
 * lặp; các sprite còn lại có alpha để vẽ đè lên sàn.
 */

export const ASSETS = {
  floorA:
    "data:image/webp;base64,",
  floorB:
    "data:image/webp;base64,",
  wallStrip:
    "data:image/webp;base64,",
  robot:
    "data:image/webp;base64,",
  crate:
    "data:image/webp;base64,",
  switchBlue:
    "data:image/webp;base64,",
  switchViolet:
    "data:image/webp;base64,",
  portalCyan:
    "data:image/webp;base64,",
  portalViolet:
    "data:image/webp;base64,",
  exit:
    "data:image/webp;base64,",
  exitTri:
    "data:image/webp;base64,",
  emitter:
    "data:image/webp;base64,",
};

/** Tạo và decode Image cho toàn bộ ASSETS; trả về map name → HTMLImageElement. */
export function loadImages() {
  const out = {};
  for (const [k, v] of Object.entries(ASSETS)) {
    const im = new Image();
    im.decoding = "async";
    im.src = v;
    out[k] = im;
  }
  return out;
}

/** Ảnh đã sẵn sàng vẽ chưa (decode xong, hợp lệ). */
export const ready = (im) => !!(im && im.complete && im.naturalWidth > 0);
